glsl:
vec4 effect(vec2 uv) {
  vec4 acc = vec4(0.0);
  vec2 d = uv - 0.5; d.x *= uRatio;
  for (int i = -8; i <= 8; i++) {
    float a = float(i) * 0.006 * uAmount;
    vec2 r = vec2(d.x * cos(a) - d.y * sin(a), d.x * sin(a) + d.y * cos(a));
    r.x /= uRatio;
    acc += getColor(r + 0.5);
  }
  return acc / 17.0;
}
